import os

def _load_holidays():
    """Parse calendars/company_2025.ics and return a set of dates (YYYY-MM-DD) that are holidays."""
    ics_path = os.path.join('calendars', 'company_2025.ics')
    if not os.path.exists(ics_path):
        return set()
    holidays = set()
    with open(ics_path, 'r', encoding='utf-8') as f:
        lines = f.read().splitlines()
    # Simple state machine for events
    i = 0
    while i < len(lines):
        line = lines[i].strip()
        if line == 'BEGIN:VEVENT':
            start = None
            end = None
            i += 1
            while i < len(lines) and lines[i].strip() != 'END:VEVENT':
                l = lines[i].strip()
                if l.startswith('DTSTART'):
                    # DTSTART[;...]:value
                    val = l.split(':', 1)[1]
                    start = datetime.datetime.strptime(val, '%Y%m%d').date()
                elif l.startswith('DTEND'):
                    val = l.split(':', 1)[1]
                    end = datetime.datetime.strptime(val, '%Y%m%d').date()
                i += 1
            # If only start provided, treat as single day
            if start and not end:
                holidays.add(start.strftime('%Y-%m-%d'))
            elif start and end:
                cur = start
                while cur <= end:
                    holidays.add(cur.strftime('%Y-%m-%d'))
                    cur += datetime.timedelta(days=1)
        else:
            i += 1
    return holidays

