def fizzbuzz(n: int) -> list:
    """Return the FizzBuzz strings for 1..n ('Fizz' for multiples of 3, 'Buzz' for 5, 'FizzBuzz' for both)."""
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def sort_versions(vs: list) -> list:
    """Sort semantic version strings ascending by (major, minor, patch)."""
    def key(v):
        parts = v.split('.')
        # Ensure exactly three parts, pad with zeros if needed
        major, minor, patch = (int(p) for p in parts + ['0'] * (3 - len(parts)))
        return (major, minor, patch)
    return sorted(vs, key=key)

def flatten(xs: list) -> list:
    """Flatten an arbitrarily nested list of ints, preserving left-to-right order."""
    result = []
    for item in xs:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

