def sentiment(text: str) -> float:
    """Return sentiment score in [-1, 1] rounded to 3 decimals.
    The model is expected to return a float in that range.
    """
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    # Some models expect a list-like input
    try:
        score = _model.predict([text])[0]
    except AttributeError:
        # Fallback: model has a transform or predict_proba
        try:
            score = _model.transform([text])[0]
        except Exception:
            raise
    # Ensure numeric and clamp to [-1,1]
    try:
        score = float(score)
    except Exception:
        raise ValueError("Model output could not be converted to float")
    if score < -1:
        score = -1.0
    elif score > 1:
        score = 1.0
    return round(score, 3)

def merge_intervals(iv: list) -> list:
    """Merge overlapping [start, end] intervals; return them sorted by start. Touching intervals merge."""
    if not iv:
        return []
    # sort by start
    iv_sorted = sorted(iv, key=lambda x: x[0])
    merged = [iv_sorted[0]]
    for current in iv_sorted[1:]:
        last = merged[-1]
        # if current starts before or at last end, merge
        if current[0] <= last[1]:
            # update end to max
            last[1] = max(last[1], current[1])
        else:
            merged.append(current)
    return merged

def c_to_f(c: float) -> float:
    """Convert Celsius to Fahrenheit (F = C * 9/5 + 32), rounded to 1 decimal."""
    return round(c * 9 / 5 + 32, 1)

def dedupe(xs: list) -> list:
    """Remove duplicates, keeping the first occurrence of each element in original order."""
    seen = set()
    result = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result

def valid_parens(s: str) -> bool:
    """Return True if every (, [, { is closed by the matching bracket in the right order."""
    # Mapping of closing to opening brackets
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in pairs.values():  # opening bracket
            stack.append(ch)
        elif ch in pairs:  # closing bracket
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
        else:
            # ignore any other characters
            continue
    return not stack

